-- Additive review metadata; existing published reviews and revisions stay intact.
BEGIN;
ALTER TABLE human_reviews ADD COLUMN integrity_checks jsonb NOT NULL DEFAULT '{}',
 ADD COLUMN client_key uuid, ADD COLUMN submission_hash char(64);
ALTER TABLE human_reviews ADD CONSTRAINT human_reviews_integrity_checks_object CHECK (jsonb_typeof(integrity_checks)='object');
CREATE UNIQUE INDEX human_reviews_submission_client_key ON human_reviews(assignment_id,client_key) WHERE client_key IS NOT NULL;
ALTER TABLE review_revision_items ADD COLUMN criterion_key varchar(80), ADD COLUMN locator varchar(500), ADD COLUMN quotation text;
DO $seed$
DECLARE artifact jsonb; criterion jsonb; template_id uuid; version_id uuid; criterion_id uuid; ord integer; n integer;
 labels text[] := ARRAY['Poor / Không đạt','Weak / Cần sửa nhiều','Adequate / Đạt cơ bản','Good / Tốt','Excellent / Rất tốt'];
 anchors text[] := ARRAY['Essential information is missing or scientifically unsupported.','Substantial weaknesses require specific corrections.','Core requirements are met, with identified limitations.','Clear, well-supported work with minor improvements.','Precise, rigorous and well-supported treatment for this artifact type.'];
BEGIN
 FOR artifact IN SELECT value FROM jsonb_array_elements($rubrics$[{"artifactType": "RESEARCH_PAPER", "criteria": [{"key": "research_problem", "title": "Research Problem & Research Questions", "description": "Clear, justified and answerable research questions.", "weight": 10}, {"key": "originality", "title": "Originality & Scientific Contributions", "description": "Distinct contributions compared with existing work.", "weight": 10}, {"key": "literature", "title": "Literature Review & Related Work", "description": "Critical coverage of relevant, credible prior research.", "weight": 10}, {"key": "methodology", "title": "Methodology & Reproducibility", "description": "A justified method, sufficient detail and reproducibility.", "weight": 20}, {"key": "data_evaluation", "title": "Data, Experiments & Evaluation", "description": "Data provenance, evaluation design, baselines and appropriate analysis.", "weight": 15}, {"key": "results_discussion", "title": "Results, Discussion & Limitations", "description": "Supported conclusions, uncertainty, limitations and interpretation.", "weight": 15}, {"key": "writing", "title": "Scientific Writing, Structure & Presentation", "description": "Coherent structure, precise writing and readable figures.", "weight": 10}, {"key": "references", "title": "References & Citation Accuracy", "description": "Traceable and accurate attribution to relevant sources.", "weight": 10}]}, {"artifactType": "RESEARCH_PROPOSAL", "criteria": [{"key": "research_problem", "title": "Research Problem & Research Questions", "description": "Clear, justified and answerable research questions.", "weight": 10}, {"key": "originality", "title": "Originality & Scientific Contributions", "description": "Distinct contributions compared with existing work.", "weight": 10}, {"key": "literature", "title": "Literature Review & Related Work", "description": "Critical coverage of relevant, credible prior research.", "weight": 10}, {"key": "methodology", "title": "Proposed Methodology & Reproducibility", "description": "Judge the planned method, not experiments that have not been conducted.", "weight": 20}, {"key": "data_evaluation", "title": "Data Access & Evaluation Plan", "description": "Feasible collection, access, ethics and planned validation.", "weight": 15}, {"key": "results_discussion", "title": "Feasibility, Risks & Expected Contribution", "description": "Justified expectations, timeline, risks and limitations, not invented results.", "weight": 15}, {"key": "writing", "title": "Scientific Writing, Structure & Presentation", "description": "Coherent structure, precise writing and readable figures.", "weight": 10}, {"key": "references", "title": "References & Citation Accuracy", "description": "Traceable and accurate attribution to relevant sources.", "weight": 10}]}, {"artifactType": "LITERATURE_REVIEW", "criteria": [{"key": "research_problem", "title": "Research Problem & Research Questions", "description": "Clear, justified and answerable research questions.", "weight": 10}, {"key": "originality", "title": "Synthesis Contribution", "description": "An identifiable analytical contribution beyond listing papers.", "weight": 10}, {"key": "literature", "title": "Coverage & Source Selection", "description": "Transparent scope and justified source coverage.", "weight": 10}, {"key": "methodology", "title": "Search & Synthesis Method", "description": "A reproducible search or a clearly explained narrative selection approach.", "weight": 20}, {"key": "data_evaluation", "title": "Evidence Appraisal", "description": "Quality and relevance of the reviewed sources, not laboratory experiments.", "weight": 15}, {"key": "results_discussion", "title": "Synthesis, Contradictions & Limitations", "description": "Critical synthesis, contrary evidence and limits of coverage.", "weight": 15}, {"key": "writing", "title": "Scientific Writing, Structure & Presentation", "description": "Coherent structure, precise writing and readable figures.", "weight": 10}, {"key": "references", "title": "References & Citation Accuracy", "description": "Traceable and accurate attribution to relevant sources.", "weight": 10}]}, {"artifactType": "METHODOLOGY", "criteria": [{"key": "research_problem", "title": "Research Problem & Research Questions", "description": "Clear, justified and answerable research questions.", "weight": 10}, {"key": "originality", "title": "Originality & Scientific Contributions", "description": "Distinct contributions compared with existing work.", "weight": 10}, {"key": "literature", "title": "Literature Review & Related Work", "description": "Critical coverage of relevant, credible prior research.", "weight": 10}, {"key": "methodology", "title": "Methodology & Reproducibility", "description": "A justified method, sufficient detail and reproducibility.", "weight": 20}, {"key": "data_evaluation", "title": "Validation Strategy", "description": "Validation appropriate to the method and current stage.", "weight": 15}, {"key": "results_discussion", "title": "Assumptions, Risks & Limitations", "description": "Explain methodological assumptions and validity threats.", "weight": 15}, {"key": "writing", "title": "Scientific Writing, Structure & Presentation", "description": "Coherent structure, precise writing and readable figures.", "weight": 10}, {"key": "references", "title": "References & Citation Accuracy", "description": "Traceable and accurate attribution to relevant sources.", "weight": 10}]}, {"artifactType": "THESIS_CHAPTER", "criteria": [{"key": "research_problem", "title": "Research Problem & Research Questions", "description": "Clear, justified and answerable research questions.", "weight": 10}, {"key": "originality", "title": "Originality & Scientific Contributions", "description": "Distinct contributions compared with existing work.", "weight": 10}, {"key": "literature", "title": "Literature Review & Related Work", "description": "Critical coverage of relevant, credible prior research.", "weight": 10}, {"key": "methodology", "title": "Methodology & Reproducibility", "description": "A justified method, sufficient detail and reproducibility.", "weight": 20}, {"key": "data_evaluation", "title": "Data, Experiments & Evaluation", "description": "Data provenance, evaluation design, baselines and appropriate analysis.", "weight": 15}, {"key": "results_discussion", "title": "Results, Discussion & Limitations", "description": "Supported conclusions, uncertainty, limitations and interpretation.", "weight": 15}, {"key": "writing", "title": "Scientific Writing, Structure & Presentation", "description": "Coherent structure, precise writing and readable figures.", "weight": 10}, {"key": "references", "title": "References & Citation Accuracy", "description": "Traceable and accurate attribution to relevant sources.", "weight": 10}]}, {"artifactType": "THESIS_DRAFT", "criteria": [{"key": "research_problem", "title": "Research Problem & Research Questions", "description": "Clear, justified and answerable research questions.", "weight": 10}, {"key": "originality", "title": "Originality & Scientific Contributions", "description": "Distinct contributions compared with existing work.", "weight": 10}, {"key": "literature", "title": "Literature Review & Related Work", "description": "Critical coverage of relevant, credible prior research.", "weight": 10}, {"key": "methodology", "title": "Methodology & Reproducibility", "description": "A justified method, sufficient detail and reproducibility.", "weight": 20}, {"key": "data_evaluation", "title": "Data, Experiments & Evaluation", "description": "Data provenance, evaluation design, baselines and appropriate analysis.", "weight": 15}, {"key": "results_discussion", "title": "Results, Discussion & Limitations", "description": "Supported conclusions, uncertainty, limitations and interpretation.", "weight": 15}, {"key": "writing", "title": "Scientific Writing, Structure & Presentation", "description": "Coherent structure, precise writing and readable figures.", "weight": 10}, {"key": "references", "title": "References & Citation Accuracy", "description": "Traceable and accurate attribution to relevant sources.", "weight": 10}]}, {"artifactType": "SOFTWARE_RESEARCH_PROJECT", "criteria": [{"key": "research_problem", "title": "Research Problem & Research Questions", "description": "Clear, justified and answerable research questions.", "weight": 10}, {"key": "originality", "title": "Originality & Scientific Contributions", "description": "Distinct contributions compared with existing work.", "weight": 10}, {"key": "literature", "title": "Literature Review & Related Work", "description": "Critical coverage of relevant, credible prior research.", "weight": 10}, {"key": "methodology", "title": "Research Design & Work Plan", "description": "Align research questions, methods, deliverables and reproducibility.", "weight": 20}, {"key": "data_evaluation", "title": "Data, Resources & Evaluation Plan", "description": "Assess feasible access and evaluation plans, not completed experiments.", "weight": 15}, {"key": "results_discussion", "title": "Timeline, Risks & Limitations", "description": "Realistic milestones, dependencies and validity risks.", "weight": 15}, {"key": "writing", "title": "Scientific Writing, Structure & Presentation", "description": "Coherent structure, precise writing and readable figures.", "weight": 10}, {"key": "references", "title": "References & Citation Accuracy", "description": "Traceable and accurate attribution to relevant sources.", "weight": 10}]}]$rubrics$::jsonb) LOOP
  template_id:=gen_random_uuid(); version_id:=gen_random_uuid();
  INSERT INTO review_templates(id,name,source,artifact_type,submission_type,status,active,version,updated_at)
   VALUES(template_id,'LumiGap Scientific Manuscript Review Rubric v1.0 · ' || (artifact->>'artifactType'),'SYSTEM',artifact->>'artifactType',artifact->>'artifactType','PUBLISHED',true,1,now());
  INSERT INTO review_template_versions(id,template_id,version_number,review_mode,description,guidelines,status,published_at)
   VALUES(version_id,template_id,1,'RUBRIC_ASSESSMENT','LumiGap internal guidance, not a publisher-mandated scoring standard.',
   ARRAY['LumiGap Scientific Manuscript Review Rubric v1.0','No default scores. NOT_ASSESSED is not zero. Use N/A only where permitted.','Weighted average uses assessed applicable criteria; coverage is shown separately. No score threshold grants approval.','Explain the issue, why it matters, where it occurs and the requested improvement.','Integrity concerns need human review, never an AI-detector misconduct verdict.','Internal readiness is not journal or conference acceptance.'],'PUBLISHED',now());
  ord:=0;
  FOR criterion IN SELECT value FROM jsonb_array_elements(artifact->'criteria') LOOP
   criterion_id:=gen_random_uuid();
   INSERT INTO review_criteria(id,template_id,version_id,key,label,description,weight,"order",required,allow_not_applicable,updated_at)
    VALUES(criterion_id,template_id,version_id,criterion->>'key',criterion->>'title',criterion->>'description',(criterion->>'weight')::float,ord,true,false,now());
   FOR n IN 1..5 LOOP
    INSERT INTO review_criterion_levels(criterion_id,label,description,score,position) VALUES(criterion_id,labels[n],(criterion->>'description') || ' ' || anchors[n],n,n-1);
   END LOOP;
   ord:=ord+1;
  END LOOP;
  UPDATE review_templates SET active_version_id=version_id WHERE id=template_id;
 END LOOP;
END $seed$;
COMMIT;
